from typing import Literal
import mas_operators as operator
from . import prompt as prompt_custom
from scripts.async_llm import create_llm_instance


from scripts.evaluator import DatasetType

class Workflow:
    def __init__(
        self,
        name: str,
        llm_config,
        dataset: DatasetType,
        aggregator_llm_config=None,
    ) -> None:
        self.name = name
        self.dataset = dataset
        self.llm = create_llm_instance(llm_config)
        self.aggregator_llm = create_llm_instance(aggregator_llm_config) if aggregator_llm_config else self.llm

    async def __call__(self, problem: str):
        """
        Optimized workflow: debate-based Caesar decryption with cross-checking aggregation.
        """
        debate = operator.Debate(worker_llm=self.llm, aggregator_llm=self.aggregator_llm, num_agents=3, worker_prompts=[prompt_custom.CAESAR_DEBATE_WORKER_PROMPT] * 3, aggregator_prompt=prompt_custom.CAESAR_DEBATE_AGG_PROMPT, n_rounds=2)
        solution = await debate(problem)
        worker_usage = self.llm.get_usage_delta() or {"total_input_tokens": 0, "total_output_tokens": 0, "total_cost": 0.0}
        if self.aggregator_llm is self.llm:
            aggregator_usage = {"total_input_tokens": 0, "total_output_tokens": 0, "total_cost": 0.0}
        else:
            aggregator_usage = self.aggregator_llm.get_usage_delta() or {"total_input_tokens": 0, "total_output_tokens": 0, "total_cost": 0.0}
        return solution["response"] or "```text\n\n```", {
            "worker": worker_usage,
            "aggregator": aggregator_usage,
        }
